  $text=fn($n=500)=>['type'=>'string','minLength'=>1,'maxLength'=>$n];$obj=fn($p)=>['type'=>'object','properties'=>$p,'required'=>array_keys($p),'additionalProperties'=>false];$list=fn($item,$min,$max)=>['type'=>'array','items'=>$item,'minItems'=>$min,'maxItems'=>$max];$num=['type'=>'integer','minimum'=>1,'maximum'=>12];
  $edge=$obj(['from'=>$num,'to'=>$num,'outgoing_end'=>$text(),'incoming_start'=>$text(),'method'=>['type'=>'string','enum'=>['cut','match_action','dissolve','fade','cutaway']],'reason'=>$text(),'transition_ms'=>['type'=>'integer','minimum'=>0,'maximum'=>500],'continuity'=>$list($obj(['dimension'=>['type'=>'string','enum'=>self::DIMENSIONS],'applicable'=>['type'=>'boolean'],'requirement'=>$text(300)]),6,6),'audio'=>$obj(['strategy'=>['type'=>'string','enum'=>['cut','pause','j_cut','l_cut','continuous']],'instruction'=>$text()]),'api'=>$obj(['outgoing'=>$text(),'incoming'=>$text()]),'postproduction'=>$text(),'checks'=>$list($text(300),1,6),'frame_reviews'=>$list($obj(['side'=>['type'=>'string','enum'=>['outgoing_end','incoming_start']],'status'=>['type'=>'string','enum'=>['reuse_candidate','needs_redesign','needs_fact']],'reason'=>$text(300)]),2,2)]);
  $n=max(0,count($facts['scenes'])-1);return $obj(['summary'=>$text(1000),'boundaries'=>$list($edge,$n,$n),'notes'=>$list($text(),0,8)]);
 }
 public function validate(array $d,array $facts):array{
  $rules=['p'=>'required|array:summary,boundaries,notes','p.summary'=>'required|string|max:1000','p.boundaries'=>'present|array|list|size:'.max(0,count($facts['scenes'])-1),'p.boundaries.*'=>'required|array:from,to,outgoing_end,incoming_start,method,reason,transition_ms,continuity,audio,api,postproduction,checks,frame_reviews','p.boundaries.*.from'=>'required|integer|min:1|max:12','p.boundaries.*.to'=>'required|integer|min:1|max:12','p.boundaries.*.method'=>'required|in:cut,match_action,dissolve,fade,cutaway','p.boundaries.*.transition_ms'=>'required|integer|min:0|max:500','p.boundaries.*.continuity'=>'required|array|list|size:6','p.boundaries.*.continuity.*'=>'required|array:dimension,applicable,requirement','p.boundaries.*.continuity.*.dimension'=>'required|in:'.implode(',',self::DIMENSIONS),'p.boundaries.*.continuity.*.applicable'=>'required|boolean','p.boundaries.*.continuity.*.requirement'=>'required|string|max:300','p.boundaries.*.audio'=>'required|array:strategy,instruction','p.boundaries.*.audio.strategy'=>'required|in:cut,pause,j_cut,l_cut,continuous','p.boundaries.*.audio.instruction'=>'required|string|max:500','p.boundaries.*.api'=>'required|array:outgoing,incoming','p.boundaries.*.api.outgoing'=>'required|string|max:500','p.boundaries.*.api.incoming'=>'required|string|max:500','p.boundaries.*.checks'=>'required|array|list|min:1|max:6','p.boundaries.*.checks.*'=>'required|string|max:300','p.boundaries.*.frame_reviews'=>'required|array|list|size:2','p.boundaries.*.frame_reviews.*'=>'required|array:side,status,reason','p.boundaries.*.frame_reviews.*.side'=>'required|in:outgoing_end,incoming_start','p.boundaries.*.frame_reviews.*.status'=>'required|in:reuse_candidate,needs_redesign,needs_fact','p.boundaries.*.frame_reviews.*.reason'=>'required|string|max:300','p.notes'=>'present|array|list|max:8','p.notes.*'=>'required|string|max:500'];
