  foreach($d['boundaries'] as $i=>$e){$bad=$e['from']!==$i+1||$e['to']!==$i+2||count(array_unique(array_column($e['continuity'],'dimension')))!==6||array_column($e['frame_reviews'],'side')!==['outgoing_end','incoming_start']||(!in_array($e['method'],['dissolve','fade'],true)&&$e['transition_ms']!==0)||(in_array($e['method'],['dissolve','fade'],true)&&$e['transition_ms']===0);if($bad)throw ValidationException::withMessages(['transitions'=>'跨段必须逐一相邻、检查项完整且不重复；切镜不新增过渡时间。']);}
